const item = $input.first().json;
const body = item.payload || {};
const rawPhone = String(body.recipientPhone || '').trim();
const cleanPhone = rawPhone.replace(/\D/g, '');
const fileUrl = String(body.fileUrl || '').trim();
const invoiceNumber = String(body.invoiceNumber || 'Invoice').replace(/[^a-zA-Z0-9._-]/g, '-');
const customerName = String(body.customerName || 'there').trim();
const amountFormatted = String(body.amountFormatted || '').trim();

let validationError = '';
if (cleanPhone.length < 8 || cleanPhone.length > 15) {
  validationError = 'recipientPhone must be a valid international phone number (8-15 digits).';
} else if (!fileUrl.startsWith('https://')) {
  validationError = 'fileUrl is required and must start with https://.';
}

const filename = `${invoiceNumber}.pdf`;
const amountPart = amountFormatted ? ` (${amountFormatted})` : '';
const caption = body.caption
  ? String(body.caption)
  : `Hi ${customerName}, here is your invoice ${invoiceNumber}${amountPart} from ${item.companyName}. ${item.supportContact}`;

return [{
  json: {
    isValid: validationError === '',
    validationError,
    cleanPhone,
    fileUrl,
    invoiceNumber,
    filename,
    caption,
  },
}];
